// frontend/src/components/workflows/Workflows.js
import React, { useMemo, useState } from "react";

// ---- constants ----
const VIEW_OPTIONS = [
  { value: "", label: "--Select a Value--" },
  { value: "pending-estimates", label: "Pending Estimates to be Submitted" },
  { value: "pending-lead", label: "Projects Pending Lead Assignment" },
  { value: "pending-roi", label: "Projects Pending ROI Update" },
];

// ---- reusable zebra table ----
function ZebraTable({ columns, rows, rowKey = "id", actionsRenderer }) {
  return (
    <div className="overflow-x-auto">
      <table className="min-w-full border border-gray-200 rounded-lg">
        <thead className="bg-gray-100">
          <tr>
            {columns.map((col) => (
              <th
                key={col.key}
                className="text-left text-sm font-semibold px-3 py-2 border-b border-gray-200"
                style={{ whiteSpace: "nowrap" }}
              >
                {col.label}
              </th>
            ))}
            {actionsRenderer ? (
              <th className="text-left text-sm font-semibold px-3 py-2 border-b border-gray-200">
                Actions
              </th>
            ) : null}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr className="odd:bg-white even:bg-gray-50">
              <td
                className="px-3 py-3 text-sm text-gray-600"
                colSpan={columns.length + (actionsRenderer ? 1 : 0)}
              >
                No records to display.
              </td>
            </tr>
          ) : (
            rows.map((row, idx) => (
              <tr
                key={row[rowKey] ?? idx}
                className={idx % 2 === 0 ? "bg-white" : "bg-gray-50"}
              >
                {columns.map((col) => (
                  <td
                    key={col.key}
                    className="px-3 py-2 text-sm text-gray-800 border-t border-gray-100"
                  >
                    {col.render ? col.render(row[col.key], row) : row[col.key]}
                  </td>
                ))}
                {actionsRenderer ? (
                  <td className="px-3 py-2 text-sm border-t border-gray-100">
                    {actionsRenderer(row)}
                  </td>
                ) : null}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

// ---- page component (TOP-LEVEL export) ----
export default function Workflows() {
  const [view, setView] = useState("");
  const [leadSelections, setLeadSelections] = useState({});

  // mock data (replace with API later)
  const pendingEstimatesData = useMemo(
    () => [
      {
        id: "PE-1001",
        project: "CBPT-Online Banking Enhancements",
        pendingWithLead: "alex.taylor@cibc.com",
        estimateDueDate: "2025-10-25",
      },
      {
        id: "PE-1002",
        project: "CBPT-Mobile App Accessibility",
        pendingWithLead: "sam.lee@cibc.com",
        estimateDueDate: "2025-10-27",
      },
    ],
    []
  );

  const pendingLeadAssignData = useMemo(
    () => [
      {
        id: "LA-2001",
        project: "Payments Modernization – Phase 2",
        domain: "Payments",
        release: "CBPT_DEP_R14",
        sitStartDate: "2025-11-04",
      },
      {
        id: "LA-2002",
        project: "Wealth Portfolio Rebalance",
        domain: "Wealth",
        release: "CBPT_DEP_R14",
        sitStartDate: "2025-11-12",
      },
    ],
    []
  );

  const availableLeads = useMemo(
    () => [
      { value: "", label: "-- Pick a Lead --" },
      { value: "alex.taylor@cibc.com", label: "Alex Taylor" },
      { value: "sam.lee@cibc.com", label: "Sam Lee" },
      { value: "ruhi.patel@cibc.com", label: "Ruhi Patel" },
      { value: "michael.chen@cibc.com", label: "Michael Chen" },
    ],
    []
  );

  const pendingRoiUpdateData = useMemo(
    () => [
      {
        id: "ROI-3001",
        project: "Credit Card Servicing Portal",
        domain: "Cards",
        automationLead: "ruhi.patel@cibc.com",
        qeLead: "michael.chen@cibc.com",
        roiDueDate: "2025-10-31",
      },
      {
        id: "ROI-3002",
        project: "Mortgage Pre-Approval Revamp",
        domain: "Lending",
        automationLead: "alex.taylor@cibc.com",
        qeLead: "sam.lee@cibc.com",
        roiDueDate: "2025-11-02",
      },
    ],
    []
  );

  // handlers (wire to backend later)
  const handleSendEstimateReminder = (row) => {
    alert(`Reminder queued for: ${row.project}`);
  };
  const handleAssignLead = (row) => {
    const chosen = leadSelections[row.id] || "";
    if (!chosen) return alert("Please pick a lead first.");
    alert(`Assigned ${chosen} to "${row.project}"`);
  };
  const handleSendRoiReminder = (row) => {
    alert(`ROI reminder queued for: ${row.project}`);
  };

  // columns
  const columnsPendingEstimates = [
    { key: "project", label: "Project" },
    { key: "pendingWithLead", label: "Estimate Pending with Lead." },
    { key: "estimateDueDate", label: "Estimate Due Date" },
  ];
  const columnsPendingLeadAssign = [
    { key: "project", label: "Project" },
    { key: "domain", label: "Domain" },
    { key: "release", label: "Release" },
    { key: "sitStartDate", label: "SIT Start date" },
    {
      key: "pickLead",
      label: "Pick a Lead",
      render: (_v, row) => (
        <select
          className="border rounded px-2 py-1 text-sm"
          value={leadSelections[row.id] || ""}
          onChange={(e) =>
            setLeadSelections((s) => ({ ...s, [row.id]: e.target.value }))
          }
        >
          {availableLeads.map((opt) => (
            <option key={opt.value + opt.label} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      ),
    },
  ];
  const columnsPendingRoi = [
    { key: "project", label: "Project" },
    { key: "domain", label: "Domain" },
    { key: "automationLead", label: "Automation Lead" },
    { key: "qeLead", label: "QE Lead" },
    { key: "roiDueDate", label: "ROI Due Date" },
  ];

  // action cells
  const actionsPendingEstimates = (row) => (
    <button
      className="text-sm px-3 py-1 rounded bg-blue-600 text-white hover:opacity-90"
      onClick={() => handleSendEstimateReminder(row)}
    >
      Send Email reminder
    </button>
  );
  const actionsPendingLeadAssign = (row) => (
    <button
      className="text-sm px-3 py-1 rounded bg-emerald-600 text-white hover:opacity-90"
      onClick={() => handleAssignLead(row)}
    >
      Assign
    </button>
  );
  const actionsPendingRoi = (row) => (
    <button
      className="text-sm px-3 py-1 rounded bg-blue-600 text-white hover:opacity-90"
      onClick={() => handleSendRoiReminder(row)}
    >
      Send Email reminder
    </button>
  );

  const renderView = () => {
    if (view === "pending-estimates") {
      return (
        <ZebraTable
          columns={columnsPendingEstimates}
          rows={pendingEstimatesData}
          actionsRenderer={actionsPendingEstimates}
        />
      );
    }
    if (view === "pending-lead") {
      return (
        <ZebraTable
          columns={columnsPendingLeadAssign}
          rows={pendingLeadAssignData}
          actionsRenderer={actionsPendingLeadAssign}
        />
      );
    }
    if (view === "pending-roi") {
      return (
        <ZebraTable
          columns={columnsPendingRoi}
          rows={pendingRoiUpdateData}
          actionsRenderer={actionsPendingRoi}
        />
      );
    }
    return (
      <div className="text-sm text-gray-600">
        Please select an option from the dropdown to continue.
      </div>
    );
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <label className="text-sm font-medium" htmlFor="showMe">
          Show Me
        </label>
        <select
          id="showMe"
          className="border rounded px-2 py-2 text-sm"
          value={view}
          onChange={(e) => setView(e.target.value)}
        >
          {VIEW_OPTIONS.map((opt) => (
            <option key={opt.value || "blank"} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      <div>{renderView()}</div>

      <style>{`
        /* fallback zebra if Tailwind is absent */
        table tr:nth-child(even) { background: #f9fafb; }
        table tr:nth-child(odd) { background: #ffffff; }
        th, td { vertical-align: middle; }
      `}</style>
    </div>
  );
}
